import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"Prompt Templates","description":"","frontmatter":{},"headers":[],"relativePath":"prompt-templates.md","filePath":"prompt-templates.md"}'),o={name:"prompt-templates.md"};function n(r,e,d,p,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="prompt-templates" tabindex="-1">Prompt Templates <a class="header-anchor" href="#prompt-templates" aria-label="Permalink to &quot;Prompt Templates&quot;">​</a></h1><p>Prompt templates turn Markdown files into reusable <code>/</code> commands. Use one when you want to reuse the same prompt without adding executable behavior or a larger set of supporting instructions.</p><p>A template can accept arguments and appear in command completion. Pi can load templates from personal configuration, project configuration, an explicit path, or a Pi package. Project configuration loads only after project trust is granted.</p><h2 id="create-a-template" tabindex="-1">Create a template <a class="header-anchor" href="#create-a-template" aria-label="Permalink to &quot;Create a template&quot;">​</a></h2><p>Create <code>~/.pi/agent/prompts/review.md</code>:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Review staged git changes</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">argument-hint: &quot;[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">focus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]&quot;</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Review the staged changes. Focus on ${1:-correctness, security, and error handling}.</span></span></code></pre></div><p>The filename becomes the command name, so this template is available as <code>/review</code>. The <code>description</code> appears in command completion. If it is omitted, Pi uses the first non-empty line.</p><p><code>argument-hint</code> is optional. Use <code>&lt;angle brackets&gt;</code> for required arguments and <code>[square brackets]</code> for optional arguments.</p><p>Run <code>/reload</code> after adding or changing a template in an active session.</p><p><a id="invoke-a-template"></a></p><h2 id="use-a-template" tabindex="-1">Use a template <a class="header-anchor" href="#use-a-template" aria-label="Permalink to &quot;Use a template&quot;">​</a></h2><p>Type the template command in the editor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span>\n<span class="line"><span>/review concurrency</span></span></code></pre></div><p>Pi expands the template before the resulting text enters the agent. Extensions receive the raw input first through the <code>input</code> event unless an extension command with the same name handles it.</p><p>Templates support these substitutions:</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Result</th></tr></thead><tbody><tr><td><code>$1</code>, <code>$2</code>, …</td><td>One positional argument</td></tr><tr><td><code>$@</code> or <code>$ARGUMENTS</code></td><td>All arguments joined with spaces</td></tr><tr><td><code>${1:-default}</code></td><td>First argument, or a default value</td></tr><tr><td><code>${@:-default}</code></td><td>All arguments, or a default value</td></tr><tr><td><code>${@:N}</code></td><td>Arguments starting at position <code>N</code></td></tr><tr><td><code>${@:N:L}</code></td><td><code>L</code> arguments starting at position <code>N</code></td></tr></tbody></table><p>Arguments follow shell-like quoting, so <code>/review &quot;API compatibility&quot;</code> supplies one argument containing a space.</p><p><a id="choose-where-it-loads"></a></p><h2 id="add-it-to-pi" tabindex="-1">Add it to Pi <a class="header-anchor" href="#add-it-to-pi" aria-label="Permalink to &quot;Add it to Pi&quot;">​</a></h2><p>Place the template in your user or project prompt directory. Conventional prompt directories load direct <code>.md</code> children only.</p><p>Settings and packages can select nested Markdown files; a package manifest can narrow discovery with explicit paths and globs. See <a href="./settings.html#resources">Settings</a> and <a href="./packages.html">Pi Packages</a> for these options.</p><p>Project templates become commands in the editor after trust is granted. Review their content before trusting an unfamiliar project. See <a href="./security.html#understand-project-trust">Security</a>.</p>',22)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
